import React from 'react';

const AddRisk = () => {
  return (
    <div style={{ padding: '2rem' }}>
      <h1>Add New Risk</h1>
      <p>This is a simplified Add Risk page.</p>

      <div style={{
        backgroundColor: '#f8fafc',
        border: '2px solid #8b5cf6',
        borderRadius: '0.5rem',
        padding: '1.5rem',
        marginTop: '2rem'
      }}>
        <h3>Magic Risk Articulation</h3>
        <textarea
          id="risk_context"
          placeholder="Paste project, business, or process context here..."
          rows={4}
          style={{
            width: '100%',
            padding: '0.75rem',
            border: '1px solid #d1d5db',
            borderRadius: '0.375rem',
            fontSize: '0.875rem',
            fontFamily: 'inherit',
            resize: 'vertical',
            minHeight: '100px'
          }}
        />
        <button
          id="articulate_risk"
          style={{
            marginTop: '1rem',
            padding: '0.75rem 1.5rem',
            backgroundColor: '#8b5cf6',
            color: 'white',
            border: 'none',
            borderRadius: '0.5rem',
            cursor: 'pointer',
            fontSize: '0.875rem',
            fontWeight: '600'
          }}
        >
          ✨ Articulate Risk
        </button>
      </div>
    </div>
  );
};

export default AddRisk;
